INSERT INTO `articles` (`id`, `title`, `description`, `content`, `image_path`, `category_name`, `author`, `views`, `reading_time`, `tags`, `is_published`, `created_at`) VALUES
(2, 'Языки программирования', 'Подробный обзор 15+ языков программирования: для чего подходят, плюсы и минусы, сложность изучения, востребованность.', '<p>Выбор первого языка программирования — важный шаг. Мы собрали подробную информацию о самых популярных языках, чтобы помочь вам сделать осознанный выбор. Для каждого языка указаны основные характеристики, области применения, преимущества и недостатки.</p>\r\n\r\n<h2>1. Python</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный (ООП, функциональное, процедурное).<br>\r\n<strong>Типизация:</strong> динамическая, строгая.<br>\r\n<strong>Когда появился:</strong> 1991, Guido van Rossum.</p>\r\n<p><strong>Для чего используют:</strong> веб-разработка (Django, Flask), анализ данных (Pandas, NumPy), машинное обучение (TensorFlow, PyTorch), автоматизация, научные вычисления.</p>\r\n<p><strong>Плюсы:</strong> простой и читаемый синтаксис (подходит для новичков), огромное сообщество и библиотеки, кроссплатформенность, быстрое прототипирование.</p>\r\n<p><strong>Минусы:</strong> низкая скорость выполнения (интерпретируемый), GIL ограничивает многопоточность, высокое потребление памяти, не подходит для мобильной разработки.</p>\r\n\r\n<h2>2. JavaScript</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный (событийно-ориентированное, функциональное, прототипное).<br>\r\n<strong>Типизация:</strong> динамическая, слабая.<br>\r\n<strong>Когда появился:</strong> 1995, Brendan Eich.</p>\r\n<p><strong>Для чего используют:</strong> фронтенд (React, Vue, Angular), бэкенд (Node.js), мобильные приложения (React Native), десктопные приложения (Electron).</p>\r\n<p><strong>Плюсы:</strong> работает в любом браузере, огромная экосистема (npm), асинхронность, гибкость.</p>\r\n<p><strong>Минусы:</strong> неочевидное поведение (особенности типов), историческая несовместимость, сложность поддержки больших проектов без строгой типизации.</p>\r\n\r\n<h2>3. Java</h2>\r\n<p><strong>Парадигма:</strong> объектно-ориентированная.<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 1995, James Gosling.</p>\r\n<p><strong>Для чего используют:</strong> корпоративные приложения (Spring), Android-разработка, веб-сервисы, банковские системы.</p>\r\n<p><strong>Плюсы:</strong> кроссплатформенность (JVM), высокая производительность, огромное сообщество и библиотеки, строгая типизация обеспечивает надёжность.</p>\r\n<p><strong>Минусы:</strong> многословный синтаксис, высокий порог входа, потребление памяти, медленный старт.</p>\r\n\r\n<h2>4. C#</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный (ООП, функциональное).<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 2000, Microsoft.</p>\r\n<p><strong>Для чего используют:</strong> игры (Unity), корпоративные приложения (ASP.NET), десктопные приложения Windows, веб-сервисы.</p>\r\n<p><strong>Плюсы:</strong> мощный язык, интеграция с .NET, LINQ, отличная производительность, современные возможности.</p>\r\n<p><strong>Минусы:</strong> историческая привязка к Windows (сейчас .NET Core кроссплатформенный), менее популярен в open-source, чем Java.</p>\r\n\r\n<h2>5. C++</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный (процедурное, ООП, обобщённое).<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 1985, Бьёрн Страуструп.</p>\r\n<p><strong>Для чего используют:</strong> системное программирование, игры, высоконагруженные приложения, встраиваемые системы, драйверы.</p>\r\n<p><strong>Плюсы:</strong> максимальная производительность, полный контроль над памятью, огромное наследие, мультипарадигмальность.</p>\r\n<p><strong>Минусы:</strong> очень сложен в изучении, ручное управление памятью (риск ошибок), долгая компиляция, нет некоторых современных абстракций.</p>\r\n\r\n<h2>6. PHP</h2>\r\n<p><strong>Парадигма:</strong> императивное, ООП, процедурное.<br>\r\n<strong>Типизация:</strong> динамическая, слабая.<br>\r\n<strong>Когда появился:</strong> 1995, Расмус Лердорф.</p>\r\n<p><strong>Для чего используют:</strong> веб-разработка (WordPress, Laravel), серверные скрипты.</p>\r\n<p><strong>Плюсы:</strong> низкий порог входа, огромное количество готовых CMS, широкое хостинг-предложение, постоянное развитие (PHP 7/8).</p>\r\n<p><strong>Минусы:</strong> непоследовательный синтаксис, исторические проблемы с безопасностью, не подходит для задач вне веба.</p>\r\n\r\n<h2>7. SQL</h2>\r\n<p><strong>Парадигма:</strong> декларативная.<br>\r\n<strong>Типизация:</strong> статическая (в зависимости от СУБД).<br>\r\n<strong>Когда появился:</strong> 1974.</p>\r\n<p><strong>Для чего используют:</strong> работа с реляционными базами данных (запросы, аналитика, отчётность).</p>\r\n<p><strong>Плюсы:</strong> стандартизирован, мощный язык для работы с данными, поддерживается всеми СУБД, оптимизирован для больших объёмов.</p>\r\n<p><strong>Минусы:</strong> не является языком общего назначения, ограниченная логика, различия в синтаксисе между СУБД.</p>\r\n\r\n<h2>8. TypeScript</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный.<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 2012, Microsoft.</p>\r\n<p><strong>Для чего используют:</strong> крупные веб-проекты, фронтенд и бэкенд (Node.js) — надстройка над JavaScript.</p>\r\n<p><strong>Плюсы:</strong> статическая типизация снижает ошибки, отличная поддержка IDE, совместимость с JavaScript, улучшает читаемость.</p>\r\n<p><strong>Минусы:</strong> дополнительный этап компиляции, кривая обучения для новичков.</p>\r\n\r\n<h2>9. Swift</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный (ООП, функциональное, протокол-ориентированное).<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 2014, Apple.</p>\r\n<p><strong>Для чего используют:</strong> разработка под iOS, macOS, watchOS, tvOS.</p>\r\n<p><strong>Плюсы:</strong> современный синтаксис, безопасный код, высокая производительность, официальная поддержка от Apple.</p>\r\n<p><strong>Минусы:</strong> привязан к экосистеме Apple, мало вакансий вне этой сферы.</p>\r\n\r\n<h2>10. Kotlin</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный (ООП, функциональное).<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 2011, JetBrains.</p>\r\n<p><strong>Для чего используют:</strong> Android-разработка, серверные приложения (совместим с Java).</p>\r\n<p><strong>Плюсы:</strong> лаконичный синтаксис, null-безопасность, полная совместимость с Java, официальный язык для Android.</p>\r\n<p><strong>Минусы:</strong> зависит от JVM, меньше популярен вне Android.</p>\r\n\r\n<h2>11. Go (Golang)</h2>\r\n<p><strong>Парадигма:</strong> процедурное, конкурентное.<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 2009, Google.</p>\r\n<p><strong>Для чего используют:</strong> микросервисы, облачные приложения, сетевые сервисы, CLI-утилиты.</p>\r\n<p><strong>Плюсы:</strong> простой синтаксис, встроенная поддержка конкурентности (goroutines), быстрая компиляция, отличная стандартная библиотека.</p>\r\n<p><strong>Минусы:</strong> ограниченная экосистема (по сравнению с Java/Python), нет дженериков (до недавнего времени).</p>\r\n\r\n<h2>12. Rust</h2>\r\n<p><strong>Парадигма:</strong> мультипарадигмальный.<br>\r\n<strong>Типизация:</strong> статическая, строгая.<br>\r\n<strong>Когда появился:</strong> 2010, Mozilla.</p>\r\n<p><strong>Для чего используют:</strong> системное программирование, встраиваемые системы, браузерные движки, блокчейн.</p>\r\n<p><strong>Плюсы:</strong> безопасность памяти без сборщика мусора, высокая производительность, современные абстракции, активное сообщество.</p>\r\n<p><strong>Минусы:</strong> крутая кривая обучения (владение, заимствование), сложный синтаксис, долгая компиляция.</p>\r\n\r\n<h2>Краткий итог: что выбрать новичку?</h2>\r\n<ul>\r\n<li>Для веб-разработки: JavaScript/TypeScript, Python, PHP.</li>\r\n<li>Для мобильных приложений: Kotlin (Android), Swift (iOS), Dart (Flutter).</li>\r\n<li>Для игр: C++, C#.</li>\r\n<li>Для науки и ИИ: Python, R, Julia.</li>\r\n<li>Для системного программирования: C, C++, Rust, Go.</li>\r\n<li>Для корпоративных систем: Java, C#.</li>\r\n<li>Первый язык: Python или JavaScript — они проще для входа.</li>\r\n</ul>\r\n<p>Выбор языка зависит от ваших целей. Не бойтесь пробовать — со временем вы освоите несколько языков и сможете выбирать подходящий для каждой задачи.</p>', 'uploads/language.jpg', 'Програмирование', 'Редакция', 21, 25, 'языки программирования, обзор', 1, '2026-02-18 15:46:55'),
(3, 'Программирование для начинающих', 'Полный гайд для тех, кто хочет стать программистом с нуля: основы, выбор языка, ресурсы, практические задания, советы.', '<p>Программирование открывает огромные возможности, но с чего начать? В этой статье мы разложим всё по полочкам: базовые понятия, как выбрать первый язык, где учиться, как практиковаться и не бросить на полпути.</p>\r\n\r\n<h2>Что нужно знать перед стартом</h2>\r\n<p>Программирование — это не только написание кода, но и умение решать задачи, логически мыслить, разбивать сложное на простые шаги. Вам не нужно быть математическим гением — достаточно усидчивости и интереса.</p>\r\n\r\n<h2>Базовые понятия (общие для всех языков)</h2>\r\n<table>\r\n<tr><th>Понятие</th><th>Описание</th><th>Пример</th></tr>\r\n<tr><td>Переменная</td><td>Именованная ячейка памяти для хранения данных</td><td><code>int age = 25;</code></td></tr>\r\n<tr><td>Типы данных</td><td>Определяют, какие значения можно хранить (числа, строки, логические)</td><td><code>int</code>, <code>float</code>, <code>string</code>, <code>bool</code></td></tr>\r\n<tr><td>Операторы</td><td>Символы для действий (+, -, *, /, ==, >)</td><td><code>if (a > b) { ... }</code></td></tr>\r\n<tr><td>Условные конструкции</td><td>Позволяют принимать решения в зависимости от условий</td><td><code>if</code>, <code>else</code>, <code>switch</code></td></tr>\r\n<tr><td>Циклы</td><td>Многократное выполнение блока кода</td><td><code>for</code>, <code>while</code></td></tr>\r\n<tr><td>Функции (методы)</td><td>Именованные блоки кода, которые можно вызывать многократно</td><td><code>function sum(a,b) { return a+b; }</code></td></tr>\r\n<tr><td>Массивы</td><td>Набор элементов одного типа</td><td><code>int[] numbers = {1,2,3};</code></td></tr>\r\n</table>\r\n\r\n<h2>Выбор первого языка</h2>\r\n<p>Мы подробно разобрали языки в статье <a href=\"article.php?id=2\">«Языки программирования»</a>. Для начинающих лучше всего подходят Python или JavaScript. Они имеют простой синтаксис, большое сообщество и множество обучающих материалов.</p>\r\n\r\n<h2>Где учиться</h2>\r\n<h3>Бесплатные ресурсы</h3>\r\n<ul>\r\n<li><strong>Stepik.org</strong> — русскоязычные курсы по программированию.</li>\r\n<li><strong>Codecademy</strong> — интерактивные уроки прямо в браузере.</li>\r\n<li><strong>freeCodeCamp</strong> — полный курс по веб-разработке с сертификатом.</li>\r\n<li><strong>Хабр Q&A</strong> — ответы на вопросы от сообщества.</li>\r\n<li><strong>YouTube-каналы:</strong> Тимофей Хирьянов (Python), Гоша Дударь, IT-каналы.</li>\r\n</ul>\r\n<h3>Платные платформы с качественным контентом</h3>\r\n<ul>\r\n<li><strong>Яндекс Практикум</strong> — структурированные курсы с наставниками.</li>\r\n<li><strong>Skillbox, Нетология, GeekBrains</strong> — курсы по разным направлениям.</li>\r\n<li><strong>Coursera, Udemy</strong> — международные курсы (часто со скидками).</li>\r\n</ul>\r\n\r\n<h2>Практические задания для закрепления</h2>\r\n<p>Теория без практики бесполезна. Начните с простых задач, затем переходите к проектам.</p>\r\n<h3>Уровень 1: синтаксис</h3>\r\n<ul>\r\n<li>Калькулятор (сложение, вычитание, умножение, деление).</li>\r\n<li>Конвертер температур (Цельсий ↔ Фаренгейт).</li>\r\n<li>Таблица умножения для заданного числа.</li>\r\n<li>Чётность числа.</li>\r\n<li>Подсчёт гласных в строке.</li>\r\n</ul>\r\n<h3>Уровень 2: коллекции и структуры данных</h3>\r\n<ul>\r\n<li>Поиск минимума и максимума в списке.</li>\r\n<li>Удаление дубликатов из списка.</li>\r\n<li>Частотный словарь слов в тексте.</li>\r\n<li>Реализация сортировки пузырьком или слиянием.</li>\r\n<li>Проверка палиндрома.</li>\r\n</ul>\r\n<h3>Уровень 3: алгоритмы и мини-проекты</h3>\r\n<ul>\r\n<li>Числа Фибоначчи (рекурсивно и итеративно).</li>\r\n<li>Проверка числа на простоту.</li>\r\n<li>Калькулятор в обратной польской нотации.</li>\r\n<li>Игра «Угадай число» или «Крестики-нолики».</li>\r\n<li>Консольный органайзер (список дел).</li>\r\n</ul>\r\n\r\n<h2>Как не бросить программирование</h2>\r\n<ul>\r\n<li><strong>Занимайтесь регулярно:</strong> лучше 30 минут каждый день, чем 5 часов раз в неделю.</li>\r\n<li><strong>Ставьте маленькие цели:</strong> не пытайтесь выучить всё сразу.</li>\r\n<li><strong>Найдите сообщество:</strong> чаты в Telegram, форумы, где можно задавать вопросы.</li>\r\n<li><strong>Работайте над проектами, которые вам интересны:</strong> сайт для друга, бот для Telegram, парсер данных.</li>\r\n<li><strong>Не бойтесь ошибок:</strong> они — часть процесса обучения. Гуглите, разбирайтесь, исправляйте.</li>\r\n<li><strong>Периодически повторяйте пройденное</strong>, чтобы закрепить знания.</li>\r\n</ul>\r\n<p>Помните: каждый эксперт когда-то был новичком. Главное — начать и не останавливаться. Удачи!</p>', 'uploads/rrog.jpg', 'Програмирование', 'Редакция', 61, 18, 'обучение, новичкам', 1, '2026-02-19 11:07:00'),
(11, 'Как составить резюме для IT-специалиста', 'Подробное руководство по составлению резюме для IT: структура, ключевые навыки, описание опыта, ошибки, примеры.', '<p>Резюме — это ваш главный инструмент при поиске работы. В IT-сфере к нему особые требования: работодатели смотрят не только на опыт, но и на навыки, проекты, стек технологий. Разберём, как составить резюме, которое выделит вас среди сотен кандидатов.</p>\r\n\r\n<h2>Структура резюме</h2>\r\n<ol>\r\n<li><strong>Личная информация</strong> (ФИО, контакты, город, желаемая должность).</li>\r\n<li><strong>Ключевые навыки (технические и soft skills).</strong></li>\r\n<li><strong>Опыт работы</strong> (в обратном хронологическом порядке).</li>\r\n<li><strong>Образование</strong> (вуз, курсы, тренинги).</li>\r\n<li><strong>Проекты</strong> (личные, коммерческие, open-source).</li>\r\n<li><strong>Достижения и сертификаты</strong> (если есть).</li>\r\n<li><strong>Дополнительная информация</strong> (языки, хобби).</li>\r\n</ol>\r\n\r\n<h2>1. Личная информация</h2>\r\n<ul>\r\n<li><strong>ФИО</strong> — лучше крупно, чтобы сразу запомнили.</li>\r\n<li><strong>Желаемая должность</strong> — например, «Frontend-разработчик (React)».</li>\r\n<li><strong>Контакты:</strong> email, телефон, ссылки на GitHub, LinkedIn, Telegram (если открыты для общения).</li>\r\n<li><strong>Город, готовность к переезду/удалёнке.</strong></li>\r\n</ul>\r\n<p>Не указывайте паспортные данные, семейное положение — это лишнее.</p>\r\n\r\n<h2>2. Ключевые навыки</h2>\r\n<p>Разделите на технические и soft skills. Для технических перечислите стеки, языки, инструменты, фреймворки, которые вы реально знаете. Группируйте по категориям (например, «Frontend: React, Redux, HTML5, CSS3, Webpack»).</p>\r\n<p><strong>Soft skills:</strong> коммуникабельность, работа в команде, тайм-менеджмент, ответственность — но лучше подкрепить примерами в разделе опыта.</p>\r\n<p><em>Важно:</em> не пишите того, чего не знаете. На собеседовании это быстро выяснится.</p>\r\n\r\n<h2>3. Опыт работы</h2>\r\n<p>Описывайте в обратном хронологическом порядке (последнее место сверху). Для каждой позиции укажите:</p>\r\n<ul>\r\n<li>Период работы (месяц/год – месяц/год).</li>\r\n<li>Название компании, должность.</li>\r\n<li>Краткое описание обязанностей (3-5 пунктов).</li>\r\n<li><strong>Главное — результаты и достижения.</strong> Вместо «писал код» лучше: «разработал модуль авторизации, сократив время входа на 20%» или «участвовал в разработке интернет-магазина с нуля, который приносит 1 млн посетителей в месяц».</li>\r\n</ul>\r\n\r\n<h2>4. Образование</h2>\r\n<p>Укажите вуз, факультет, специальность, годы обучения. Если у вас нет профильного образования — не беда, в IT это не всегда критично. Главное — курсы и самообучение.</p>\r\n<p>Перечислите значимые курсы (Яндекс.Практикум, Skillbox, Coursera) с названием и годом.</p>\r\n\r\n<h2>5. Проекты</h2>\r\n<p>Этот раздел особенно важен для новичков. Опишите 2-3 проекта, над которыми вы работали самостоятельно или в команде. Для каждого укажите:</p>\r\n<ul>\r\n<li>Название, ссылку на GitHub/работающий демо-сайт.</li>\r\n<li>Задачу, которую решали.</li>\r\n<li>Стек технологий.</li>\r\n<li>Что сделали конкретно вы.</li>\r\n</ul>\r\n<p>Например: «Интернет-магазин на React и Redux. Реализовал корзину, фильтрацию товаров, авторизацию через JWT. Деплой на Vercel».</p>\r\n\r\n<h2>6. Достижения и сертификаты</h2>\r\n<p>Участие в хакатонах, олимпиадах, публичные выступления, сертификаты AWS, Microsoft, Google и т.д.</p>\r\n\r\n<h2>7. Дополнительная информация</h2>\r\n<p>Уровень английского (читаю техническую документацию, могу вести переговоры), наличие загранпаспорта, хобби (если оно характеризует вас с полезной стороны, например, ведение блога о программировании).</p>\r\n\r\n<h2>Чего НЕ стоит делать</h2>\r\n<ul>\r\n<li><strong>Не пишите «Резюме» заголовком</strong> — и так понятно.</li>\r\n<li><strong>Не используйте шаблонные фразы</strong> («ответственный, целеустремлённый») без подтверждения.</li>\r\n<li><strong>Не делайте слишком длинным</strong> — оптимально 1-2 страницы.</li>\r\n<li><strong>Не врите</strong> — правда всплывёт на собеседовании или тестовом задании.</li>\r\n<li><strong>Не забывайте проверять орфографию</strong> — ошибки создают плохое впечатление.</li>\r\n</ul>\r\n\r\n<h2>Пример хорошего описания опыта</h2>\r\n<p><em>Frontend-разработчик, ООО «Технологии», июнь 2022 – настоящее время</em></p>\r\n<ul>\r\n<li>Разработал и внедрил новую систему управления состоянием на Redux Toolkit, что уменьшило количество багов на 30%.</li>\r\n<li>Оптимизировал производительность приложения (Lighthouse score вырос с 65 до 92).</li>\r\n<li>Участвовал в код-ревью, наставлял двух джуниоров.</li>\r\n<li>Интегрировал фронтенд с REST API, работал с WebSocket для чата.</li>\r\n</ul>\r\n\r\n<h2>Формат файла</h2>\r\n<p>Лучше всего отправлять PDF — он выглядит одинаково на всех устройствах. Название файла: Фамилия_Должность.pdf (например, Иванов_Frontend.pdf).</p>\r\n\r\n<h2>Заключение</h2>\r\n<p>Хорошее резюме — это не просто список технологий, а история о том, какую пользу вы можете принести компании. Покажите свои достижения, будьте честны и структурированы. Удачи в поиске работы!</p>', 'uploads/resume.jpg', 'Карьера', 'Ольга Васильева', 443, 8, 'резюме, карьера, поиск работы', 1, '2026-02-28 17:50:02');
INSERT INTO `languages` (`id`, `name`, `description`, `full_description`, `image_path`, `category`, `year_created`, `creator`, `paradigm`, `typing`, `popularity_rank`, `difficulty`, `pros`, `cons`) VALUES
(1, 'Python', 'Высокоуровневый язык программирования общего назначения', 'Python — интерпретируемый язык с динамической типизацией. Поддерживает несколько парадигм: ООП, функциональное, процедурное. Широко используется в веб-разработке, научных вычислениях, машинном обучении.', 'uploads/python.jpg', 'Web, Data Science', 1991, 'Guido van Rossum', 'Мультипарадигмальный', 'динамическая', 1, 'easy', 'Очень простой и читаемый синтаксис\nОгромное количество библиотек и фреймворков\nШирокое применение: веб, data science, ML, автоматизация\nКроссплатформенность\nБольшое сообщество и обилие обучающих материалов', 'Низкая скорость выполнения по сравнению с компилируемыми языками\nВысокое потребление памяти\nДинамическая типизация может приводить к ошибкам времени выполнения\nПроблемы с многопоточностью (GIL)'),
(2, 'Java', 'Объектно-ориентированный язык, платформонезависимый', 'Java — строго типизированный язык, работающий на виртуальной машине JVM. Используется для создания корпоративных приложений, Android-разработки.', 'uploads/java.jpg', 'Enterprise, Mobile', 1995, 'James Gosling', 'ООП', 'статическая', 2, 'medium', 'Платформонезависимость (JVM)\nСтрогая типизация и надёжность\nОгромная экосистема и корпоративная поддержка\nВысокая производительность\nОтличная поддержка многопоточности', 'Многословный синтаксис (много кода для простых вещей)\nВысокое потребление памяти\nДолгий старт приложений\nСложность для начинающих'),
(3, 'JavaScript', 'Язык для веб-разработки', 'JavaScript — мультипарадигмальный язык, поддерживающий событийно-ориентированное, функциональное и прототипное программирование. Основной язык фронтенда.', 'uploads/javascript.jpg', 'Web', 1995, 'Brendan Eich', 'Мультипарадигмальный', 'динамическая', 3, 'easy', 'Язык фронтенда, работает в любом браузере\nОгромное сообщество и библиотеки (npm)\nАсинхронность и событийная модель\nГибкость (множество парадигм)\nБыстрое прототипирование', 'Динамическая типизация может приводить к неожиданным ошибкам\nНеоднородность реализации в разных браузерах (исторически)\nCallback hell (хотя сейчас промисы и async/await помогают)\nСлабая типизация'),
(4, 'С#', 'Это современный, объектно-ориентированный и типобезопасный язык программирования, разработанный Microsoft в рамках платформы .NET.', 'объектно-ориентированный язык программирования общего назначения', 'uploads/Сish.jpg', 'Программирование', 1998, 'Андерс Хейлсберг и Скотт Вильтаумот', '-', '-', 4, 'medium', 'Мощный и современный язык от Microsoft\nИнтеграция с .NET и Windows\nОтличная производительность\nLINQ и функциональные возможности\nПоддержка всех современных парадигм', 'Завязан на экосистему Microsoft (хотя .NET Core теперь кроссплатформенный)\nМожет быть сложен для новичков из-за обилия возможностей\nНе так популярен в open-source, как Java/Python'),
(5, 'PHP', 'Скриптовый язык для веб-разработки', 'PHP (Hypertext Preprocessor) — интерпретируемый язык, широко используемый для создания динамических веб-сайтов и веб-приложений. Поддерживает процедурное и объектно-ориентированное программирование.', 'uploads/php.jpg', 'Web', 1995, 'Расмус Лердорф', 'Императивное, ООП, процедурное', 'динамическая', 5, 'easy', 'Специализирован для веба (легко встраивается в HTML)\nОгромное количество CMS и фреймворков (WordPress, Laravel)\nНизкий порог входа\nБольшое хостинг-предложение\nПостоянное развитие (PHP 7/8 улучшили скорость)', 'Непоследовательный синтаксис и названия функций\nИсторически плохая безопасность (при неаккуратном коде)\nСлабая типизация\nМеньше востребован в новых проектах, но legacy огромно'),
(6, 'C++', 'Компилируемый язык, расширение C', 'C++ — язык программирования, поддерживающий несколько парадигм: процедурное, объектно-ориентированное, обобщённое. Широко используется в системном программировании, играх, высоконагруженных приложениях.', 'uploads/cpp.jpg', 'Системное программирование', 1985, 'Бьёрн Страуструп', 'Мультипарадигмальный', 'статическая', 6, 'hard', 'Максимальная производительность\nПолный контроль над памятью\nШирокое использование в системном программировании, играх, embedded\nМультипарадигмальность\nОгромное наследие и библиотеки', 'Очень сложен в изучении и безопасном использовании\nРучное управление памятью (риск утечек и ошибок)\nДлительная компиляция\nОтсутствие некоторых современных абстракций (в сравнении с Rust)'),
(7, 'TypeScript', 'Надстройка над JavaScript со статической типизацией', 'TypeScript — язык, разработанный Microsoft, который добавляет в JavaScript статическую типизацию и современные возможности. Компилируется в чистый JavaScript.', 'uploads/typescript.jpg', 'Web', 2012, 'Microsoft', 'Мультипарадигмальный', 'статическая', 7, 'easy', 'Статическая типизация поверх JavaScript\nУлучшает масштабируемость и надёжность кода\nПолная совместимость с JS\nПоддержка современных возможностей\nИспользуется в крупных проектах', 'Требует компиляции в JS\nИногда сложная система типов\nДополнительный слой абстракции\nНе все библиотеки имеют типы'),
(8, 'Swift', 'Современный язык от Apple для iOS и macOS', 'Swift — безопасный и быстрый язык, пришедший на смену Objective-C. Использует современные паттерны и поддерживает протокол-ориентированное программирование.', 'uploads/swift.jpg', 'Mobile', 2014, 'Apple (Крис Латтнер)', 'Мультипарадигмальный', 'статическая', 8, 'medium', 'Современный, безопасный и быстрый\nОфициальный язык для Apple-экосистемы\nЧистый синтаксис\nПоддержка функционального и протокол-ориентированного программирования', 'Используется только для Apple-платформ (хотя есть кроссплатформенные проекты)\nМолодой, меняется быстро\nМеньше библиотек, чем у Objective-C'),
(9, 'Kotlin', 'Статически типизированный язык для JVM', 'Kotlin — язык, разработанный JetBrains, полностью совместим с Java и является официальным языком для Android-разработки. Лаконичный и выразительный.', 'uploads/kotlin.jpg', 'Mobile, Enterprise', 2011, 'JetBrains', 'Мультипарадигмальный', 'статическая', 9, 'medium', 'Полная совместимость с Java\nБолее лаконичный и современный синтаксис\nПоддержка coroutines для асинхронности\nОфициальный язык для Android\nБезопасность (null-safety)', 'Может быть медленнее Java в некоторых случаях\nИногда сложная система типов\nНе так много учебных материалов, как по Java'),
(10, 'Go', 'Компилируемый язык от Google (Golang)', 'Go — язык с простым синтаксисом, встроенной поддержкой конкурентности и быстрой компиляцией. Активно используется для создания облачных сервисов и сетевых приложений.', 'uploads/go.jpg', 'Системное программирование', 2009, 'Роб Пайк, Кен Томпсон', 'Процедурное, конкурентное', 'статическая', 10, 'easy', 'Простой и минималистичный синтаксис\nВстроенная поддержка конкурентности (goroutines)\nБыстрая компиляция\nОтличная стандартная библиотека\nЛёгкость в изучении', 'Отсутствие обобщений (дженериков) – раньше, сейчас появились\nМеньше библиотек, чем у Java/Python\nНе очень выразительный (нет наследования в классическом виде)'),
(11, 'Rust', 'Системный язык, гарантирующий безопасность памяти', 'Rust — язык, разработанный Mozilla, обеспечивающий высокую производительность и безопасность без сборщика мусора. Популярен для системного программирования и встраиваемых систем.', 'uploads/rust.jpg', 'Системное программирование', 2010, 'Грэдон Хор', 'Мультипарадигмальный', 'статическая', 11, 'hard', 'Гарантированная безопасность памяти без сборщика мусора\nВысокая производительность\nСовременные абстракции с нулевой стоимостью\nАктивное сообщество\nПодходит для системного программирования', 'Сложная кривая обучения (владение, заимствование, времена жизни)\nСтрогий компилятор замедляет разработку на начальном этапе\nНе так много библиотек, как у C++'),
(12, 'Ruby', 'Динамический язык, известный фреймворком Ruby on Rails', 'Ruby — интерпретируемый язык с элегантным синтаксисом. Основная парадигма — всё есть объект. Широко применяется в веб-разработке благодаря Rails.', 'uploads/ruby.jpg', 'Web', 1995, 'Юкихиро Мацумото', 'Мультипарадигмальный', 'динамическая', 12, 'easy', 'Элегантный и выразительный синтаксис\nБыстрая разработка (Rails)\nСильное сообщество\nВсё есть объект\nГибкость (можно переопределять методы)', 'Низкая производительность\nМеньше популярен, чем раньше\nДинамическая типизация может быть проблематичной в больших проектах\nМедленный запуск'),
(13, 'Scala', 'Мультипарадигмальный язык для JVM', 'Scala объединяет объектно-ориентированное и функциональное программирование. Компилируется в байт-код Java и широко используется в области больших данных (Apache Spark).', 'uploads/scala.jpg', 'Enterprise', 2003, 'Мартин Одерски', 'Мультипарадигмальный', 'статическая', 13, 'hard', 'Сочетает ООП и функциональное программирование\nРаботает на JVM\nМощная система типов\nИспользуется в big data (Spark)\nВыразительность', 'Сложный язык (много концепций)\nМедленная компиляция\nСложность в изучении\nНе такая большая экосистема, как у Java'),
(14, 'Dart', 'Язык от Google для фронтенда и Flutter', 'Dart — оптимизированный для UI, используется для создания мобильных, веб- и десктопных приложений с фреймворком Flutter. Имеет JIT и AOT компиляцию.', 'uploads/dart.jpg', 'Web, Mobile', 2011, 'Ларс Бак', 'Мультипарадигмальный', 'статическая', 14, 'medium', 'Язык для Flutter (кроссплатформенная мобильная разработка)\nПростой синтаксис\nБыстрая работа (JIT/AOT компиляция)\nХорошая документация\nПоддержка асинхронности', 'В основном используется только с Flutter\nМеньше библиотек вне Flutter\nМолодой язык\nНе так популярен, как JS/Java'),
(15, 'Perl', 'Универсальный скриптовый язык', 'Perl известен мощными возможностями обработки текста и огромным репозиторием модулей CPAN. Используется в системном администрировании, веб-разработке.', 'uploads/perl.jpg', 'Системное администрирование', 1987, 'Ларри Уолл', 'Мультипарадигмальный', 'динамическая', 15, 'hard', 'Мощные возможности обработки текста (регулярные выражения встроены)\nОгромный репозиторий модулей CPAN\nГибкость\nИспользуется в системном администрировании', 'Синтаксис считается перегруженным и трудночитаемым (\"write-only\")\nПадение популярности\nМало новых проектов\nСложность поддержки чужого кода'),
(16, 'R', 'Язык для статистического анализа и визуализации', 'R — среда и язык для статистических вычислений и графики. Широко применяется в анализе данных, научных исследованиях и машинном обучении.', 'uploads/r.jpg', 'Data Science', 1993, 'Росс Ihaka, Роберт Джентлмен', 'Мультипарадигмальный', 'динамическая', 16, 'medium', 'Специализирован для статистики и анализа данных\nОгромное количество пакетов для статистики\nОтличные графические возможности (ggplot2)\nАктивно используется в науке', 'Медленный\nСинтаксис непривычен для программистов\nНе подходит для общих задач\nСлабая типизация'),
(17, 'MATLAB', 'Язык для численных вычислений', 'MATLAB — проприетарный язык и среда для инженерных и научных расчётов. Поддерживает матричные операции, визуализацию и моделирование.', 'uploads/matlab.jpg', 'Научные вычисления', 1984, 'Cleve Moler', 'Императивное, процедурное', 'динамическая', 17, 'medium', 'Удобен для численных вычислений и моделирования\nОгромное количество встроенных функций\nИнтерактивная среда\nИспользуется в инженерии и науке', 'Проприетарный (дорогой)\nНе подходит для production-разработки\nМедленный\nСпецифичный синтаксис'),
(18, 'Groovy', 'Динамический язык для JVM', 'Groovy — скриптовый язык с синтаксисом, похожим на Java, но с возможностями динамической типизации и метапрограммирования. Используется для написания сценариев и в экосистеме Gradle.', 'uploads/groovy.jpg', 'Enterprise', 2003, 'James Strachan', 'Мультипарадигмальный', 'динамическая/статическая', 18, 'medium', 'Динамический язык для JVM\nПлавный переход от Java (похожий синтаксис)\nИспользуется в Gradle и Jenkins\nПоддерживает метапрограммирование', 'Меньшая популярность, чем у Java/Kotlin\nМедленнее Java\nСложности с производительностью в больших проектах'),
(19, 'Julia', 'Высокопроизводительный язык для научных вычислений', 'Julia сочетает скорость компилируемых языков с динамичностью интерпретируемых. Создан для технических расчётов и анализа данных.', 'uploads/julia.jpg', 'Data Science', 2012, 'Джефф Безансон и др.', 'Мультипарадигмальный', 'динамическая (с опциональной типизацией)', 19, 'medium', 'Высокая производительность (близка к C)\nДинамическая типизация с возможностью указывать типы\nОтлично подходит для научных вычислений\nРастущее сообщество', 'Молодой язык\nМеньше библиотек, чем у Python/R\nСтабильность ещё не идеальна\nИногда меняется синтаксис'),
(20, 'Haskell', 'Чистый функциональный язык', 'Haskell — статически типизированный язык, основанный на ленивых вычислениях. Широко используется в академической среде и для задач, требующих высокой надёжности.', 'uploads/haskell.jpg', 'Академическое', 1990, 'Комитет Haskell', 'Функциональное', 'статическая', 20, 'hard', 'Чисто функциональный язык\nЛенивые вычисления\nМощная система типов\nВысокая надёжность кода\nИспользуется в академической среде', 'Очень сложен для изучения\nМало промышленных вакансий\nНизкая производительность некоторых абстракций\nМеньше библиотек'),
(21, 'Elixir', 'Функциональный язык на основе Erlang VM', 'Elixir использует модель акторов для конкурентности и отказоустойчивости. Популярен для создания масштабируемых и распределённых систем (например, Phoenix Framework).', 'uploads/elixir.jpg', 'Web, Распределённые системы', 2011, 'Хосе Валим', 'Функциональное, конкурентное', 'динамическая', 21, 'medium', 'Функциональный язык на базе Erlang VM (BEAM)\nОтличная поддержка конкурентности и отказоустойчивости\nПростой синтаксис (вдохновлён Ruby)\nИспользуется в вебе (Phoenix)', 'Меньше популярен, чем Go/Rust\nСложность отладки распределённых систем\nМеньше библиотек\nНе для всех задач'),
(22, 'Clojure', 'Функциональный диалект Lisp для JVM', 'Clojure — язык с акцентом на неизменяемость и конкурентность. Работает на JVM, CLR и JavaScript. Используется для сложных бизнес-приложений.', 'uploads/clojure.jpg', 'Enterprise', 2007, 'Rich Hickey', 'Функциональное', 'динамическая', 22, 'hard', 'Функциональный диалект Lisp на JVM\nНеизменяемые структуры данных\nМощная макросистема\nУдобен для конкурентного программирования', 'Синтаксис Lisp необычен для многих\nМеньше вакансий\nСложность в изучении\nНе самая быстрая производительность'),
(23, 'F#', 'Функциональный язык для .NET', 'F# — мультипарадигмальный язык, входящий в экосистему .NET. Сочетает функциональное, императивное и объектно-ориентированное программирование. Используется в финансах, науке.', 'uploads/fsharp.jpg', 'Enterprise', 2005, 'Microsoft (Дон Сайм)', 'Мультипарадигмальный', 'статическая', 23, 'medium', 'Функциональный язык для .NET\nЛаконичный и безопасный\nХорошая интеграция с .NET\nПодходит для финансовых и научных задач', 'Меньше популярен, чем C#\nОграничен экосистемой Windows (хотя .NET Core кроссплатформенный)\nНе так много учебных материалов'),
(24, 'C', 'Классический системный язык программирования', 'C — компилируемый язык, лежащий в основе многих операционных систем и встраиваемых систем. Оказал огромное влияние на развитие языков программирования.', 'uploads/c.jpg', 'Системное программирование', 1972, 'Деннис Ритчи', 'Процедурное', 'статическая', 24, 'hard', 'Максимальная производительность и контроль\nБазовый язык для системного программирования\nОгромное наследие\nПортабельность (везде есть компилятор C)', 'Ручное управление памятью\nОтсутствие современных абстракций\nНизкоуровневый, требует глубоких знаний\nЛегко сделать ошибки безопасности');
INSERT INTO `professions` (`id`, `title`, `category`, `short_description`, `full_description`, `image_path`, `salary_min`, `salary_max`) VALUES
(1, 'Программист Техник', 'Програмирование', 'Специалист, сочетающий разработку ПО, системное администрирование и техническую поддержку. Обеспечивает интеграцию и бесперебойную работу программных продуктов.', '<h2>Кто такой программист-техник?</h2>\r\n<p>Программист-техник — это универсальный специалист, который работает на стыке разработки программного обеспечения и системного администрирования. В отличие от «чистого» программиста, он не только пишет код, но и отвечает за внедрение, настройку и поддержку программных продуктов в инфраструктуре компании.</p>\r\n\r\n<h2>Основные обязанности</h2>\r\n<ul>\r\n<li><strong>Разработка и доработка ПО:</strong> написание кода на языках, используемых в компании (часто Python, C++, Java), создание скриптов для автоматизации задач.</li>\r\n<li><strong>Интеграция систем:</strong> настройка взаимодействия между различными программами и базами данных, обеспечение бесшовного обмена информацией.</li>\r\n<li><strong>Администрирование серверов и баз данных:</strong> установка и настройка серверного ПО, контроль производительности, резервное копирование.</li>\r\n<li><strong>Техническая поддержка пользователей:</strong> консультирование коллег по работе с программами, решение проблем в работе ПО.</li>\r\n<li><strong>Документирование:</strong> написание инструкций, технической документации, руководств пользователя.</li>\r\n<li><strong>Обновление и модернизация:</strong> отслеживание новых версий используемого ПО, планирование и проведение обновлений.</li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li>Знание одного или нескольких языков программирования (Python, Java, C++, PHP).</li>\r\n<li>Опыт работы с базами данных (SQL, MySQL, PostgreSQL).</li>\r\n<li>Понимание сетевых технологий (TCP/IP, DNS, DHCP).</li>\r\n<li>Администрирование ОС (Windows Server, Linux).</li>\r\n<li>Навыки работы с системами контроля версий (Git).</li>\r\n<li>Основы информационной безопасности.</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Аналитическое мышление, способность разбираться в сложных системах.</li>\r\n<li>Внимательность к деталям.</li>\r\n<li>Коммуникабельность, умение объяснять технические вещи простым языком.</li>\r\n<li>Самоорганизация, умение работать с большим объёмом задач.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Программисты-техники востребованы в IT-отделах компаний различных отраслей: банки, производственные предприятия, ритейл, государственные учреждения, системные интеграторы. Они также могут работать в хостинговых компаниях, дата-центрах и сервисных центрах.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Для старта подходит среднее профессиональное или высшее образование по IT-специальностям (09.02.03 «Программирование в компьютерных системах», 09.03.02 «Информационные системы и технологии»). Начать карьеру можно с позиции техника, системного администратора или стажёра-программиста. Рост возможен до ведущего специалиста, руководителя IT-отдела или DevOps-инженера.</p>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 40 000 – 70 000 руб.</li>\r\n<li>Middle: 70 000 – 120 000 руб.</li>\r\n<li>Senior: 120 000 – 180 000 руб. и выше</li>\r\n</ul>', 'uploads/texnik.jpg', 40000, 180000),
(4, 'Програмист 1 С', 'Програмирование', 'Специалист по разработке, настройке и поддержке программных продуктов «1С:Предприятие» для автоматизации бизнес-процессов.', '<h2>Кто такой программист 1С?</h2>\r\n<p>Программист 1С — это специалист, работающий с платформой «1С:Предприятие». Он автоматизирует бухгалтерский, управленческий, кадровый и другие виды учёта, разрабатывает конфигурации, настраивает типовые решения и поддерживает их работоспособность.</p>\r\n\r\n<h2>Обязанности</h2>\r\n<ul>\r\n<li><strong>Разработка и модификация конфигураций:</strong> создание новых объектов (справочников, документов, отчётов) и доработка существующих под нужды конкретного предприятия.</li>\r\n<li><strong>Написание кода на встроенном языке 1С:</strong> реализация бизнес-логики, алгоритмов расчётов, обработок.</li>\r\n<li><strong>Интеграция с внешними системами:</strong> обмен данными с сайтами, банковскими клиентами, CRM, другими учётными системами (через HTTP-сервисы, XML, SQL).</li>\r\n<li><strong>Администрирование баз данных 1С:</strong> настройка прав доступа, резервное копирование, обновление платформы и конфигураций.</li>\r\n<li><strong>Поддержка пользователей:</strong> консультирование, поиск и исправление ошибок, обучение работе в программе.</li>\r\n<li><strong>Составление отчётности:</strong> разработка сложных отчётов и печатных форм.</li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li>Отличное знание платформы «1С:Предприятие» (версии 8.3 и выше) и типовых конфигураций (Бухгалтерия, Управление торговлей, ERP).</li>\r\n<li>Владение встроенным языком программирования 1С, знание системы компоновки данных (СКД).</li>\r\n<li>Понимание SQL, умение писать запросы к базам данных (MS SQL, PostgreSQL).</li>\r\n<li>Базовые навыки администрирования (установка, обновление, настройка серверов 1С).</li>\r\n<li>Знание принципов бухгалтерского и налогового учёта (желательно).</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Аналитический склад ума, умение разбираться в бизнес-процессах.</li>\r\n<li>Внимательность, ответственность.</li>\r\n<li>Коммуникабельность, готовность помогать пользователям.</li>\r\n<li>Способность работать с большими объёмами информации.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Программисты 1С требуются в любой компании, ведущей учёт в 1С: торговые и производственные фирмы, бюджетные учреждения, аудиторские и консалтинговые компании, IT-аутсорсинговые компании, фирмы-франчайзи 1С.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Высшее или среднее специальное образование (информационные технологии, прикладная информатика, экономика) даёт хорошую базу, но многие приходят в профессию после специализированных курсов (от 1С или учебных центров). Карьерная лестница:</p>\r\n<ul>\r\n<li>Junior 1С-программист (до 1 года) — поддержка, мелкие доработки.</li>\r\n<li>Middle 1С-программист (1-3 года) — самостоятельная разработка и внедрение задач средней сложности.</li>\r\n<li>Senior 1С-программист (более 3 лет) — сложные проекты, руководство группой, архитектура решений.</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 40 000 – 70 000 руб.</li>\r\n<li>Middle: 70 000 – 130 000 руб.</li>\r\n<li>Senior: 130 000 – 250 000 руб. и выше</li>\r\n</ul>', 'uploads/1c.jpg', 40000, 250000),
(5, 'Гейм Дизайнер', 'Дизайн, Программирование', 'Специалист, придумывающий и разрабатывающий концепцию видеоигры: механики, правила, сюжет, баланс, чтобы создать увлекательный игровой опыт.', '<h2>Кто такой гейм-дизайнер?</h2>\r\n<p>Гейм-дизайнер — это создатель идеи игры. Он определяет, во что и как будет играть пользователь: правила, цели, механики, сюжет, персонажи, уровни. Это творческая и аналитическая профессия на стыке программирования, психологии и искусства.</p>\r\n\r\n<h2>Основные обязанности</h2>\r\n<ul>\r\n<li><strong>Разработка концепции игры:</strong> придумывание жанра, сеттинга, целевой аудитории, ключевых особенностей.</li>\r\n<li><strong>Проектирование игровых механик:</strong> как игрок взаимодействует с миром, какие действия может совершать, как они влияют на игровой процесс.</li>\r\n<li><strong>Написание дизайн-документа (GDD):</strong> подробное описание всех аспектов игры для команды разработчиков.</li>\r\n<li><strong>Балансировка:</strong> настройка сложности, экономики, прогрессии, чтобы игра оставалась интересной, но не слишком лёгкой или сложной.</li>\r\n<li><strong>Работа с художниками и программистами:</strong> постановка задач, контроль реализации, тестирование прототипов.</li>\r\n<li><strong>Создание нарратива:</strong> если игра сюжетная — написание диалогов, сценария, лора.</li>\r\n<li><strong>Тестирование и итерации:</strong> играть в собственную игру, выявлять недостатки и предлагать улучшения.</li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li>Знание основ геймдизайна: механики, динамика, эстетика (MDA framework).</li>\r\n<li>Навыки работы с игровыми движками (Unity, Unreal Engine) на уровне понимания и настройки.</li>\r\n<li>Основы скриптинга (для создания прототипов).</li>\r\n<li>Работа с системами контроля версий (Git).</li>\r\n<li>Грамотная устная и письменная речь (для описания идей и документов).</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Креативность, способность генерировать нестандартные идеи.</li>\r\n<li>Аналитическое мышление, умение декомпозировать задачи.</li>\r\n<li>Понимание психологии игрока: что мотивирует, что вызывает интерес, а что — раздражение.</li>\r\n<li>Коммуникабельность, работа в команде.</li>\r\n<li>Усидчивость и внимание к деталям.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Гейм-дизайнеры работают в студиях разработки игр (мобильных, PC, консольных), инди-командах, компаниях, создающих игровые приложения для образования или бизнеса (геймификация).</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Специальных вузовских программ по геймдизайну мало, но есть курсы (Skillbox, Нетология, Scream School). Также полезно профильное образование в IT, дизайне или психологии. Начинать можно с тестировщика игр, младшего дизайнера или самостоятельно делать прототипы. Карьерный рост:</p>\r\n<ul>\r\n<li>Junior Game Designer</li>\r\n<li>Middle Game Designer</li>\r\n<li>Senior Game Designer</li>\r\n<li>Lead Game Designer</li>\r\n<li>Creative Director</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 40 000 – 80 000 руб.</li>\r\n<li>Middle: 80 000 – 150 000 руб.</li>\r\n<li>Senior: 150 000 – 300 000 руб. и выше</li>\r\n</ul>', 'uploads/gamedis.jpg', 40000, 300000),
(6, 'Тестировщик', 'Тестирование, Программирование', 'Специалист, отвечающий за качество программного продукта. Ищет ошибки, проверяет соответствие требованиям, помогает улучшить пользовательский опыт.', '<h2>Кто такой тестировщик (QA-инженер)?</h2>\r\n<p>QA (Quality Assurance) — это обеспечение качества. Тестировщик не просто ищет баги, он участвует в процессе разработки на всех этапах, чтобы предотвратить появление дефектов и гарантировать, что продукт соответствует ожиданиям пользователей.</p>\r\n\r\n<h2>Обязанности</h2>\r\n<ul>\r\n<li><strong>Анализ требований:</strong> изучение документации, участие в обсуждениях, чтобы понять, как должна работать система.</li>\r\n<li><strong>Проектирование тестов:</strong> написание тест-кейсов, чек-листов, сценариев для проверки функциональности.</li>\r\n<li><strong>Ручное тестирование:</strong> выполнение тестов, проверка новых функций, регрессионное тестирование (чтобы старые функции не сломались).</li>\r\n<li><strong>Автоматизированное тестирование (опционально):</strong> написание скриптов для автоматической проверки (Selenium, Cypress, JUnit).</li>\r\n<li><strong>Регистрация дефектов:</strong> заведение багов в трекере (Jira, Redmine, YouTrack), подробное описание шагов воспроизведения.</li>\r\n<li><strong>Взаимодействие с командой:</strong> обсуждение проблем с разработчиками, уточнение требований с аналитиками.</li>\r\n<li><strong>Составление отчётности:</strong> отчёты о тестировании, статистика.</li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li>Понимание методологий разработки (Waterfall, Agile, Scrum).</li>\r\n<li>Знание теории тестирования: виды тестов, техники тест-дизайна, уровни тестирования.</li>\r\n<li>Навыки работы с баг-трекинговыми системами (Jira, Redmine).</li>\r\n<li>Базовое знание SQL (для проверки данных в БД).</li>\r\n<li>Понимание клиент-серверной архитектуры, HTTP-протокола.</li>\r\n<li>Для автоматизаторов: знание языков программирования (Python, Java, JS) и фреймворков (Selenium, Appium).</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Внимательность к мелочам.</li>\r\n<li>Аналитический склад ума, умение выявлять неочевидные ситуации.</li>\r\n<li>Критическое мышление — не принимать ничего на веру.</li>\r\n<li>Коммуникабельность и умение аргументировать.</li>\r\n<li>Терпение и усидчивость.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Тестировщики требуются в любой IT-компании, разрабатывающей ПО: веб-студии, продуктовые компании, аутсорсинговые фирмы, банки, государственные учреждения.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Можно прийти с любым техническим образованием, а также с курсов. Путь от джуниора до сеньора занимает 3-5 лет. Специализации:</p>\r\n<ul>\r\n<li>Ручное тестирование (Manual QA)</li>\r\n<li>Автоматизация тестирования (Automation QA)</li>\r\n<li>Нагрузочное тестирование (Performance QA)</li>\r\n<li>Безопасность (Security QA)</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 40 000 – 70 000 руб.</li>\r\n<li>Middle: 70 000 – 140 000 руб.</li>\r\n<li>Senior: 140 000 – 250 000 руб. и выше</li>\r\n</ul>', 'uploads/testing.jpg', 40000, 250000),
(7, 'Мобильный Разработчик', 'Разработка, Програмирование', 'Создаёт приложения для мобильных устройств (смартфоны, планшеты) на платформах Android (Kotlin, Java) или iOS (Swift).', '<h2>Кто такой мобильный разработчик?</h2>\r\n<p>Мобильный разработчик пишет программы для мобильных устройств. Он отвечает за интерфейс, логику, взаимодействие с сервером и публикацию в магазинах приложений. Специалисты обычно делятся на Android- и iOS-разработчиков, но есть и кроссплатформенные (Flutter, React Native).</p>\r\n\r\n<h2>Обязанности</h2>\r\n<ul>\r\n<li><strong>Разработка приложений:</strong> написание кода на Java/Kotlin (Android) или Swift (iOS), реализация функциональности согласно требованиям.</li>\r\n<li><strong>Проектирование архитектуры:</strong> выбор паттернов (MVP, MVVM, Clean Architecture), организация модулей.</li>\r\n<li><strong>Работа с UI:</strong> создание интерфейсов, адаптация под разные экраны, анимации.</li>\r\n<li><strong>Интеграция с бэкендом:</strong> работа с REST API, WebSockets, загрузка данных, синхронизация.</li>\r\n<li><strong>Работа с локальными базами данных:</strong> сохранение данных на устройстве (SQLite, Room, Core Data).</li>\r\n<li><strong>Тестирование и отладка:</strong> написание unit-тестов, инструментальных тестов, исправление багов.</li>\r\n<li><strong>Публикация и поддержка:</strong> загрузка в App Store/Google Play, мониторинг отзывов, выпуск обновлений.</li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li><strong>Для Android:</strong> Kotlin/Java, Android SDK, Android Studio, знание компонентов (Activity, Fragment, Service, BroadcastReceiver), популярные библиотеки (Retrofit, Glide, Dagger, Coroutines).</li>\r\n<li><strong>Для iOS:</strong> Swift, Xcode, UIKit/SwiftUI, CocoaPods, SPM, работа с фреймворками Apple, знание паттернов (MVC, MVVM).</li>\r\n<li><strong>Кроссплатформа:</strong> Dart/Flutter, React Native (JavaScript).</li>\r\n<li>Понимание принципов ООП, SOLID.</li>\r\n<li>Знание Git, CI/CD (GitHub Actions, Bitrise).</li>\r\n<li>Основы UI/UX-дизайна.</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Любовь к мобильным технологиям, интерес к новым версиям ОС и библиотекам.</li>\r\n<li>Терпение (отладка на разных устройствах может быть утомительной).</li>\r\n<li>Внимание к деталям, особенно в интерфейсе.</li>\r\n<li>Умение работать в команде с дизайнерами и бэкендерами.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Мобильные разработчики востребованы в продуктовых компаниях (банки, маркетплейсы, сервисы доставки), студиях мобильной разработки, стартапах, на фрилансе.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Высшее техническое образование (ПОИТ, ИВТ) желательно, но не обязательно. Многие приходят после курсов (Яндекс.Практикум, Skillbox, Udemy). Карьера:</p>\r\n<ul>\r\n<li>Junior (до 1 года) — поддержка, простые задачи.</li>\r\n<li>Middle (1-3 года) — самостоятельная разработка, участие в архитектуре.</li>\r\n<li>Senior (3-5 лет) — лидерство, сложные проекты, менторство.</li>\r\n<li>Team Lead / Architect.</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 60 000 – 100 000 руб.</li>\r\n<li>Middle: 100 000 – 200 000 руб.</li>\r\n<li>Senior: 200 000 – 350 000 руб. и выше</li>\r\n</ul>', 'uploads/mobile.jpg', 60000, 350000),
(8, 'Облачный Программист', 'Программирование, Облако', 'Специалист по облачным технологиям, проектирующий и поддерживающий облачную инфраструктуру, автоматизирующий развертывание и обеспечивающий безопасность.', '<h2>Кто такой облачный программист (Cloud Engineer)?</h2>\r\n<p>Облачный программист (Cloud Engineer) занимается созданием, развертыванием и управлением приложениями и сервисами в облачных средах (AWS, Google Cloud, Azure, Yandex Cloud). Он сочетает навыки разработчика и системного администратора с фокусом на облачные технологии.</p>\r\n\r\n<h2>Обязанности</h2>\r\n<ul>\r\n<li><strong>Проектирование облачной архитектуры:</strong> выбор сервисов (виртуальные машины, бессерверные функции, базы данных, хранилища), оптимизация затрат.</li>\r\n<li><strong>Развёртывание приложений:</strong> настройка инфраструктуры как код (IaC) с помощью Terraform, CloudFormation, Pulumi.</li>\r\n<li><strong>Автоматизация процессов:</strong> написание скриптов (Python, Bash), настройка CI/CD (GitLab CI, GitHub Actions, Jenkins) для автоматического деплоя.</li>\r\n<li><strong>Обеспечение безопасности:</strong> управление доступом (IAM), шифрование данных, настройка сетевых политик, мониторинг угроз.</li>\r\n<li><strong>Мониторинг и логирование:</strong> настройка сбора метрик (CloudWatch, Stackdriver), алертов, централизованного логирования.</li>\r\n<li><strong>Оптимизация производительности и стоимости:</strong> анализ использования ресурсов, рекомендации по масштабированию, использование резервных мощностей (spot instances).</li>\r\n<li><strong>Миграция локальных приложений в облако.</strong></li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li>Опыт работы с одним или несколькими облачными провайдерами (AWS, GCP, Azure). Желательно наличие сертификатов (AWS Certified Solutions Architect, Google Associate Cloud Engineer).</li>\r\n<li>Знание инфраструктуры как код: Terraform, CloudFormation, Ansible.</li>\r\n<li>Контейнеризация и оркестрация: Docker, Kubernetes (особенно в облачных managed-сервисах типа EKS, GKE, AKS).</li>\r\n<li>Языки программирования/скриптов: Python, Go, Bash, PowerShell.</li>\r\n<li>Системы управления версиями (Git).</li>\r\n<li>CI/CD инструменты (GitLab CI, Jenkins, CircleCI).</li>\r\n<li>Сетевые технологии (VPC, DNS, балансировка, VPN).</li>\r\n<li>Мониторинг и логи (Prometheus, Grafana, ELK stack, CloudWatch).</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Системное мышление, способность видеть картину целиком.</li>\r\n<li>Склонность к автоматизации и стандартизации.</li>\r\n<li>Внимательность к деталям (безопасность, конфигурации).</li>\r\n<li>Аналитические способности для оптимизации затрат.</li>\r\n<li>Коммуникабельность для взаимодействия с разработчиками.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Облачные инженеры требуются в компаниях, которые используют облака: от стартапов до крупных корпораций, а также в облачных провайдерах, системных интеграторах и консалтинговых фирмах.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Высшее образование (ПОИТ, ИВТ, ИБ) желательно. Путь начинается с позиции системного администратора или разработчика, затем углубление в облака. Сертификации сильно помогают. Карьера:</p>\r\n<ul>\r\n<li>Junior Cloud Engineer</li>\r\n<li>Cloud Engineer</li>\r\n<li>Senior Cloud Engineer</li>\r\n<li>Cloud Architect / Lead Cloud Engineer</li>\r\n<li>DevOps Engineer (близкая специализация)</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 60 000 – 100 000 руб.</li>\r\n<li>Middle: 100 000 – 180 000 руб.</li>\r\n<li>Senior: 180 000 – 300 000 руб. и выше</li>\r\n</ul>', 'uploads/cloud.jpg', 60000, 300000),
(9, 'специалист по кибербезопасности', 'Программирование, Безопасность', 'Защищает информационные системы от взломов, утечек данных и других угроз. Проводит аудит безопасности, разрабатывает политики защиты и реагирует на инциденты.', '<h2>Кто такой специалист по кибербезопасности?</h2>\r\n<p>Специалист по кибербезопасности (Information Security Specialist) обеспечивает защиту данных, приложений и инфраструктуры компании от внешних и внутренних угроз. Он выявляет уязвимости, предотвращает атаки и расследует инциденты.</p>\r\n\r\n<h2>Обязанности</h2>\r\n<ul>\r\n<li><strong>Анализ защищённости:</strong> проведение тестов на проникновение (pentest), анализ кода, сканирование уязвимостей.</li>\r\n<li><strong>Разработка и внедрение политик безопасности:</strong> регламенты доступа, использование паролей, шифрование.</li>\r\n<li><strong>Мониторинг событий безопасности:</strong> анализ логов, работа с SIEM-системами (Splunk, ArcSight, MaxPatrol), обнаружение инцидентов.</li>\r\n<li><strong>Реагирование на инциденты:</strong> расследование взломов, сбор цифровых улик, восстановление после атак.</li>\r\n<li><strong>Управление уязвимостями:</strong> отслеживание обновлений, настройка средств защиты (IDS/IPS, антивирусы, DLP).</li>\r\n<li><strong>Обучение сотрудников:</strong> проведение тренингов по кибергигиене.</li>\r\n<li><strong>Взаимодействие с государственными органами</strong> (ФСТЭК, ФСБ) в части сертификации и лицензирования.</li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li>Понимание сетевых протоколов (TCP/IP, HTTP, DNS) и архитектуры ОС (Windows, Linux).</li>\r\n<li>Знание типов атак и методов защиты: SQL-инъекции, XSS, CSRF, переполнение буфера, фишинг.</li>\r\n<li>Опыт работы со средствами защиты: межсетевые экраны (Cisco ASA, pfSense), антивирусы, DLP-системы, IDS/IPS (Snort, Suricata).</li>\r\n<li>Навыки тестирования на проникновение: использование Metasploit, Kali Linux, Burp Suite, Nmap.</li>\r\n<li>Знание законодательства в области защиты информации (152-ФЗ о персональных данных, ГОСТы).</li>\r\n<li>Базовые навыки программирования (Python, Bash) для автоматизации и анализа кода.</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Аналитическое мышление и исследовательский интерес.</li>\r\n<li>Высокая ответственность и этичность.</li>\r\n<li>Внимательность к деталям.</li>\r\n<li>Стрессоустойчивость (при инцидентах).</li>\r\n<li>Постоянное самообучение (новые угрозы появляются каждый день).</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Банки, финтех-компании, крупные корпорации, государственные учреждения, компании-разработчики ПО, IT-аутсорсеры, специализированные фирмы по кибербезопасности.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Требуется высшее образование по специальностям «Информационная безопасность», «Компьютерная безопасность» или смежным. Сертификации (CISSP, CISM, CEH) высоко ценятся. Карьера:</p>\r\n<ul>\r\n<li>Специалист по ИБ (Junior)</li>\r\n<li>Инженер по ИБ (Middle)</li>\r\n<li>Ведущий инженер / Руководитель отдела ИБ</li>\r\n<li>Архитектор безопасности / CISO</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 50 000 – 90 000 руб.</li>\r\n<li>Middle: 90 000 – 170 000 руб.</li>\r\n<li>Senior: 170 000 – 300 000 руб. и выше</li>\r\n</ul>', 'uploads/securitu.jpg', 50000, 300000),
(10, 'Фуллстек разработчик', 'Разработка, Программирование, Дизайн', 'Универсальный разработчик, владеющий как фронтендом (клиентская часть), так и бэкендом (серверная часть, базы данных). Способен создать полноценное веб-приложение самостоятельно.', '<h2>Кто такой фуллстек-разработчик?</h2>\r\n<p>Fullstack-разработчик — это специалист широкого профиля, который работает и с внешним видом сайта (фронтенд), и с его внутренней логикой (бэкенд). Он понимает все этапы создания веб-приложения и может вести проект от идеи до развёртывания.</p>\r\n\r\n<h2>Обязанности</h2>\r\n<ul>\r\n<li><strong>Анализ требований:</strong> совместно с заказчиком или аналитиком определяет функциональность и архитектуру.</li>\r\n<li><strong>Разработка фронтенда:</strong> вёрстка (HTML, CSS), программирование интерактивности (JavaScript, фреймворки React/Vue/Angular), адаптация под мобильные устройства.</li>\r\n<li><strong>Разработка бэкенда:</strong> написание серверного кода (Node.js, Python, PHP, Java, C#), создание API (REST, GraphQL).</li>\r\n<li><strong>Работа с базами данных:</strong> проектирование схем, написание запросов (SQL, NoSQL).</li>\r\n<li><strong>Интеграция внешних сервисов:</strong> платёжные системы, API соцсетей, внешние API.</li>\r\n<li><strong>Настройка развёртывания:</strong> деплой на хостинг/облако, настройка веб-сервера (nginx, Apache), работа с CI/CD.</li>\r\n<li><strong>Тестирование:</strong> написание юнит-тестов, интеграционных тестов, ручное тестирование.</li>\r\n<li><strong>Поддержка и доработка существующих проектов.</strong></li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li><strong>Фронтенд:</strong> HTML, CSS (Flexbox, Grid), JavaScript (ES6+), один из фреймворков (React, Vue, Angular).</li>\r\n<li><strong>Бэкенд:</strong> один из языков (JavaScript/Node.js, Python/Django/Flask, PHP/Laravel, Java/Spring, C#/ASP.NET).</li>\r\n<li><strong>Базы данных:</strong> реляционные (MySQL, PostgreSQL) и нереляционные (MongoDB, Redis).</li>\r\n<li><strong>API:</strong> создание и потребление RESTful API, понимание GraphQL.</li>\r\n<li><strong>Веб-серверы:</strong> настройка nginx, Apache.</li>\r\n<li><strong>Системы контроля версий:</strong> Git, GitHub/GitLab.</li>\r\n<li><strong>Базовые навыки DevOps:</strong> Docker, CI/CD, деплой.</li>\r\n<li><strong>Основы UI/UX-дизайна</strong> (чтобы понимать макеты).</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Широкий кругозор, способность быстро осваивать новые технологии.</li>\r\n<li>Системное мышление, умение видеть проект целиком.</li>\r\n<li>Способность решать разнообразные задачи без помощи других специалистов.</li>\r\n<li>Коммуникабельность для работы с заказчиком и командой.</li>\r\n<li>Самоорганизация, особенно на фрилансе.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Веб-студии, продуктовые компании, стартапы (особенно ценятся), на фрилансе. Часто фуллстек-разработчики являются ключевыми сотрудниками в небольших командах.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Можно прийти из смежных областей (фронтенд или бэкенд). Хорошие курсы (Яндекс.Практикум, Skillbox) дают базу. Карьера:</p>\r\n<ul>\r\n<li>Junior Fullstack Developer</li>\r\n<li>Middle Fullstack Developer</li>\r\n<li>Senior Fullstack Developer</li>\r\n<li>Tech Lead / Solution Architect</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 60 000 – 100 000 руб.</li>\r\n<li>Middle: 100 000 – 180 000 руб.</li>\r\n<li>Senior: 180 000 – 300 000 руб. и выше</li>\r\n</ul>', 'uploads/fullstake.jpg', 60000, 300000),
(11, 'Промт инженер', 'Нейросети, Промт, Разработка', 'Специалист по взаимодействию с нейросетями. Разрабатывает эффективные запросы (промпты) для генерации текста, изображений, кода и другого контента с помощью ИИ.', '<h2>Кто такой промпт-инженер (Prompt Engineer)?</h2>\r\n<p>Промпт-инженер — это новая профессия на стыке лингвистики, психологии и IT. Он формулирует задания для искусственного интеллекта (языковых моделей вроде GPT, Midjourney, Stable Diffusion) так, чтобы получать качественные, точные и полезные результаты. По сути, он учит нейросеть понимать, что от неё хотят.</p>\r\n\r\n<h2>Обязанности</h2>\r\n<ul>\r\n<li><strong>Разработка и тестирование промптов:</strong> создание текстовых инструкций для нейросетей, эксперименты с формулировками, уточнение контекста, подбор примеров (few-shot).</li>\r\n<li><strong>Оптимизация результатов:</strong> анализ ответов ИИ, итеративное улучшение запросов, чтобы добиться нужного стиля, тона, фактологической точности.</li>\r\n<li><strong>Создание библиотеки шаблонов:</strong> разработка готовых промптов для типовых задач компании (написание статей, генерация кода, аналитика, перевод).</li>\r\n<li><strong>Настройка поведения модели:</strong> использование параметров (температура, топ-р, частота), чтобы влиять на креативность и повторяемость.</li>\r\n<li><strong>Взаимодействие с разработчиками:</strong> интеграция ИИ-моделей в приложения через API, помощь в создании продуктов на основе ИИ.</li>\r\n<li><strong>Обучение сотрудников:</strong> проведение тренингов по эффективному использованию нейросетей.</li>\r\n<li><strong>Мониторинг новых моделей и техник:</strong> область развивается стремительно, нужно быть в курсе.</li>\r\n</ul>\r\n\r\n<h2>Необходимые навыки</h2>\r\n<h3>Технические навыки</h3>\r\n<ul>\r\n<li>Понимание принципов работы языковых моделей (особенности, ограничения, как они обрабатывают запросы).</li>\r\n<li>Знание основ программирования (Python, работа с API, JSON) — для автоматизации и интеграции.</li>\r\n<li>Навыки анализа данных (чтобы оценивать качество ответов).</li>\r\n<li>Английский язык на уровне чтения документации и общения с моделями (они лучше понимают английский).</li>\r\n<li>Опыт работы с конкретными ИИ-инструментами: ChatGPT, Claude, Gemini, Midjourney, DALL-E, Stable Diffusion.</li>\r\n</ul>\r\n<h3>Личные качества</h3>\r\n<ul>\r\n<li>Креативность, умение нестандартно формулировать задачи.</li>\r\n<li>Аналитическое мышление, способность выявлять паттерны.</li>\r\n<li>Грамотная письменная речь (на русском и английском).</li>\r\n<li>Терпение и усидчивость (иногда нужно много итераций).</li>\r\n<li>Любознательность, интерес к новым технологиям.</li>\r\n</ul>\r\n\r\n<h2>Где работать?</h2>\r\n<p>Промпт-инженеры востребованы в IT-компаниях, разрабатывающих продукты на базе ИИ, в маркетинговых агентствах (для генерации контента), в медиа, в отделах автоматизации бизнеса, на фрилансе. Крупные корпорации (Яндекс, Тинькофф, Сбер) также ищут таких специалистов.</p>\r\n\r\n<h2>Образование и карьера</h2>\r\n<p>Профессия новая, специальных вузовских программ пока нет. Приходят люди с разным бэкграундом: программисты, лингвисты, журналисты, маркетологи. Полезно пройти специализированные курсы (например, на Stepik, в Яндекс.Практикуме). Карьера:</p>\r\n<ul>\r\n<li>Junior Prompt Engineer / AI-тренер</li>\r\n<li>Prompt Engineer</li>\r\n<li>Senior Prompt Engineer / Lead AI Specialist</li>\r\n<li>Product Manager AI-решений</li>\r\n</ul>\r\n\r\n<h2>Уровень зарплат</h2>\r\n<ul>\r\n<li>Junior: 50 000 – 90 000 руб.</li>\r\n<li>Middle: 90 000 – 160 000 руб.</li>\r\n<li>Senior: 160 000 – 300 000 руб. и выше</li>\r\n</ul>', 'uploads/promt.jpg', 50000, 300000);
