INSERT INTO `results` (`id`, `test_id`, `min_score`, `max_score`, `result_text`, `result_type`) VALUES
(4, 3, 0, 2, 'Начальный уровень. Рекомендуем изучить основы программирования.', 'text'),
(5, 3, 3, 4, 'Средний уровень. Вы уже знакомы с основами, можно углубляться.', 'text'),
(6, 3, 5, 6, 'Продвинутый уровень. Отличные знания!', 'text'),
(7, 4, -5, 0, 'Вам подойдут скриптовые языки: Python, JavaScript.', 'text'),
(8, 4, 1, 3, 'Выбирайте языки с сильной типизацией: Java, C#.', 'text'),
(9, 4, 4, 5, 'Вам ближе системное программирование: C, C++.', 'text'),
(10, 5, -5, 0, 'Вы склонны избегать конфликтов. Развивайте навыки коммуникации.', 'text'),
(11, 5, 1, 3, 'Вы адекватно реагируете на рабочие ситуации.', 'text'),
(12, 5, 4, 5, 'Вы лидер, умеете брать ответственность.', 'text'),
(13, 6, -5, -2, 'Тип \"Человек-Техника\"', 'text'),
(14, 6, -1, 2, 'Тип \"Человек-Человек\"', 'text'),
(15, 6, 3, 5, 'Тип \"Человек-Природа\" или \"Человек-Знак\"', 'text'),
(16, 1, -30, -11, 'Программирование, вероятно, не ваше призвание. Возможно, вам подойдут другие направления, где меньше аналитической работы и больше общения или творчества.', 'text'),
(17, 1, -10, 0, 'У вас есть некоторые склонности к программированию, но нужно больше практики и интереса. Попробуйте начать с основ: почитайте статьи, посмотрите вводные уроки, чтобы понять, ваше ли это.', 'text'),
(18, 1, 1, 10, 'У вас неплохие задатки! Стоит попробовать себя в программировании. Выберите язык для начинающих (Python или JavaScript) и попробуйте написать простые программы.', 'text'),
(19, 1, 11, 30, 'Отличная предрасположенность! Программирование может стать вашей профессией. Рекомендуем углублённое изучение и создание собственных проектов.', 'text'),
(20, 7, -10, -4, 'Ваш стиль – **исследовательский**. Вы любите экспериментировать, пробовать новое, вам быстро становится скучно от рутины. Из вас получится отличный разработчик в стартапе, исследователь прототипов, специалист по новым технологиям. Старайтесь документировать свои эксперименты, чтобы не терять результаты.', 'text'),
(21, 7, -3, 3, 'Ваш стиль – **структурный**. Вы цените стабильность, предсказуемость, любите использовать готовые шаблоны и проверенные решения. Вам подойдёт работа над поддержкой legacy-кода, типовыми проектами, где важна надёжность. Не бойтесь иногда выходить за рамки – это поможет росту.', 'text'),
(22, 7, 4, 8, 'Ваш стиль – **образный**. Вы мыслите картинками, вам важна эстетика и удобство. Возможно, вам стоит обратить внимание на фронтенд-разработку, дизайн интерфейсов, UX. Ваши решения часто интуитивно понятны пользователям.', 'text'),
(23, 7, 9, 20, 'Ваш стиль – **логический**. Вы – прирождённый аналитик. Вам подходят задачи, требующие построения сложных алгоритмов, оптимизации, работы с данными. Хороший бэкенд-разработчик или архитектор ПО. Главное – не забывайте про обратную связь от пользователей.', 'text');
INSERT INTO `slides` (`id`, `title`, `description`, `image_path`, `test_id`, `sort_order`, `active`) VALUES
(1, 'Определение профессиональных склонностей', 'Пройдите тест и узнайте, к какому типу профессий вы склонны по методике Климова.', 'uploads/pro.jpg', NULL, 1, 1),
(2, 'Тест на знание программирования', 'Проверьте свои базовые знания в области программирования: алгоритмы, структуры данных.', 'uploads/slide2.jpg', 3, 2, 1);
INSERT INTO `tests` (`id`, `title`, `description`, `questions_count`, `duration_min`, `age_limit`, `price`, `image_path`, `rating`, `show_in_menu`, `slug`) VALUES
(1, 'Тест? Подходит ли мне программирование?', 'Тест о програмировании', 15, 30, 14, '0.00', 'uploads/prog.jpg', 4, 1, '0'),
(3, 'Тест на знание программирования', 'Проверьте свои базовые знания в области программирования: алгоритмы, структуры данных.', 5, 15, 14, '0.00', 'uploads/test2.jpg', 4.2, 1, 'programming-knowledge'),
(4, 'Какой язык программирования тебе подходит?', 'Определите, какой язык программирования лучше всего соответствует вашему складу ума.', 5, 12, 12, '0.00', 'uploads/language.jpg', 4, 1, '0'),
(5, 'Симулятор ситуации на работе', 'Оцените свою реакцию в реальных рабочих ситуациях и получите рекомендации.', 5, 20, 16, '0.00', 'uploads/test_6995869009b1e.jpg', 4, 1, '0'),
(6, 'Опросник Климова (классический)', 'Классический тест на профориентацию от академика Климова. Узнайте свой тип личности.', 5, 10, 12, '0.00', 'uploads/test_6995861302d79.png', 4, 1, '0'),
(7, 'Ваш стиль мышления в программировании', 'Определите, какой тип мышления преобладает у вас при решении задач: логическое, образное, структурное или исследовательское.', 10, 15, 14, '0.00', 'uploads/mindset_test.jpg', 0, 1, 'mindset');
