(36, 4, 'Что означает аббревиатура JVM?', 'single', '[{\"id\": \"a\", \"text\": \"Java Virtual Machine\", \"correct\": true}, {\"id\": \"b\", \"text\": \"JavaScript Version Manager\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Java Visual Machine\", \"correct\": false}]', NULL, 2, 6),
(37, 4, 'Какой язык был разработан компанией Microsoft и широко используется в корпоративной среде?', 'single', '[{\"id\": \"a\", \"text\": \"C#\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Java\", \"correct\": false}, {\"id\": \"c\", \"text\": \"PHP\", \"correct\": false}]', NULL, 2, 7),
(38, 4, 'Напишите название языка, который является надмножеством JavaScript и добавляет статическую типизацию.', 'text', NULL, NULL, 5, 8),
(39, 4, 'Какой язык чаще всего ассоциируется с фреймворком Ruby on Rails?', 'single', '[{\"id\": \"a\", \"text\": \"Ruby\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Python\", \"correct\": false}, {\"id\": \"c\", \"text\": \"PHP\", \"correct\": false}]', NULL, 2, 9),
(40, 4, 'Какой язык гарантирует безопасность памяти без сборщика мусора?', 'single', '[{\"id\": \"a\", \"text\": \"Rust\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Go\", \"correct\": false}, {\"id\": \"c\", \"text\": \"C++\", \"correct\": false}]', NULL, 2, 10),
(41, 5, 'Что делать, если вы заметили ошибку в коде, но никто её не видит?', 'single', '[{\"id\": \"a\", \"text\": \"Сообщить команде и предложить исправить\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Исправить молча, чтобы не отвлекать\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Подождать, пока кто-то заметит\", \"correct\": false}]', NULL, 2, 1),
(42, 5, 'Коллега просит помощи, а у вас срочный дедлайн. Ваши действия?', 'single', '[{\"id\": \"a\", \"text\": \"Объяснить ситуацию и предложить помочь позже\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Отказать, сославшись на занятость\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Бросить свои дела и помочь\", \"correct\": false}]', NULL, 2, 2),
(43, 5, 'Как реагировать на невыполнимые требования заказчика?', 'single', '[{\"id\": \"a\", \"text\": \"Предложить альтернативное решение, объяснив риски\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Выполнять, что сказали\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Обвинить заказчика в некомпетентности\", \"correct\": false}]', NULL, 2, 3),
(44, 5, 'Какие качества помогают эффективно работать в команде? (выберите все)', 'multiple', '[{\"id\": \"a\", \"text\": \"Коммуникабельность\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Замкнутость\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Ответственность\", \"correct\": true}, {\"id\": \"d\", \"text\": \"Игнорирование чужого мнения\", \"correct\": false}]', NULL, 3, 4),
(45, 5, 'Что такое \"код-ревью\"?', 'single', '[{\"id\": \"a\", \"text\": \"Процесс проверки кода другими разработчиками\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Написание кода заново\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Тестирование программы\", \"correct\": false}]', NULL, 2, 5),
(46, 5, 'Напишите одно правило, которое помогает избегать конфликтов в команде.', 'text', NULL, NULL, 5, 6),
(47, 5, 'Как поступить, если вы не согласны с архитектурным решением, принятым командой?', 'single', '[{\"id\": \"a\", \"text\": \"Аргументированно высказать своё мнение на обсуждении\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Промолчать и сделать по-своему\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Написать жалобу начальнику\", \"correct\": false}]', NULL, 2, 7),
(48, 5, 'Что такое \"deadline\"?', 'single', '[{\"id\": \"a\", \"text\": \"Крайний срок сдачи работы\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Мёртвая линия в коде\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Название бага\", \"correct\": false}]', NULL, 2, 8),
(49, 5, 'Как правильно давать обратную связь коллеге?', 'single', '[{\"id\": \"a\", \"text\": \"Конструктивно, по делу, без перехода на личности\", \"correct\": true}, {\"id\": \"b\", \"text\": \"В агрессивной форме, чтобы запомнил\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Никак, пусть сам догадается\", \"correct\": false}]', NULL, 2, 9),
(50, 5, 'Вы провалили важный проект. Ваши действия?', 'single', '[{\"id\": \"a\", \"text\": \"Проанализировать ошибки и предложить план исправления\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Уволиться\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Обвинить других\", \"correct\": false}]', NULL, 2, 10),
(51, 6, 'Какой тип профессий по Климову предполагает работу с растениями и животными?', 'single', '[{\"id\": \"a\", \"text\": \"Человек-Природа\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Человек-Техника\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Человек-Человек\", \"correct\": false}]', NULL, 2, 1),
(52, 6, 'К какому типу относится профессия бухгалтера?', 'single', '[{\"id\": \"a\", \"text\": \"Человек-Знак\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Человек-Художественный образ\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Человек-Техника\", \"correct\": false}]', NULL, 2, 2),
(53, 6, 'Профессия учителя относится к типу:', 'single', '[{\"id\": \"a\", \"text\": \"Человек-Человек\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Человек-Природа\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Человек-Знак\", \"correct\": false}]', NULL, 2, 3),
(54, 6, 'Какие из перечисленных профессий относятся к типу \"Человек-Техника\"? (выберите все)', 'multiple', '[{\"id\": \"a\", \"text\": \"Инженер\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Водитель\", \"correct\": true}, {\"id\": \"c\", \"text\": \"Художник\", \"correct\": false}, {\"id\": \"d\", \"text\": \"Программист\", \"correct\": true}]', NULL, 3, 4),
(55, 6, 'Кто автор классификации профессий по предмету труда?', 'single', '[{\"id\": \"a\", \"text\": \"Е.А. Климов\", \"correct\": true}, {\"id\": \"b\", \"text\": \"А.Н. Леонтьев\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Л.С. Выготский\", \"correct\": false}]', NULL, 2, 5),
(56, 6, 'Какой тип профессий связан с созданием и преобразованием художественных образов?', 'single', '[{\"id\": \"a\", \"text\": \"Человек-Художественный образ\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Человек-Знак\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Человек-Природа\", \"correct\": false}]', NULL, 2, 6),
(57, 6, 'Назовите любой тип профессий по Климову (напишите одним словом).', 'text', NULL, NULL, 5, 7),
(58, 6, 'К какому типу относится профессия \"журналист\"?', 'single', '[{\"id\": \"a\", \"text\": \"Человек-Человек\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Человек-Знак\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Человек-Техника\", \"correct\": false}]', NULL, 2, 8),
(59, 6, 'Профессия \"дизайнер\" ближе всего к типу:', 'single', '[{\"id\": \"a\", \"text\": \"Человек-Художественный образ\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Человек-Техника\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Человек-Знак\", \"correct\": false}]', NULL, 2, 9),
(60, 6, 'Что означает тип \"Человек-Знак\"?', 'single', '[{\"id\": \"a\", \"text\": \"Работа с информацией, цифрами, текстами\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Работа с людьми\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Работа с техникой\", \"correct\": false}]', NULL, 2, 10),
(61, 7, 'Какой стиль мышления характерен для человека, который любит строить чёткие логические цепочки?', 'single', '[{\"id\": \"a\", \"text\": \"Логический\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Образный\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Исследовательский\", \"correct\": false}]', NULL, 2, 1),
(62, 7, 'Что такое \"визуальное мышление\"?', 'single', '[{\"id\": \"a\", \"text\": \"Представление информации в виде образов\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Пошаговый анализ\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Решение задач методом проб\", \"correct\": false}]', NULL, 2, 2),
(63, 7, 'Какие черты присущи исследовательскому стилю? (выберите все)', 'multiple', '[{\"id\": \"a\", \"text\": \"Экспериментирование\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Склонность к новому\", \"correct\": true}, {\"id\": \"c\", \"text\": \"Предпочтение готовых шаблонов\", \"correct\": false}, {\"id\": \"d\", \"text\": \"Быстрое переключение\", \"correct\": true}]', NULL, 3, 3),
(64, 7, 'Какой стиль мышления чаще всего выбирают архитекторы и дизайнеры интерфейсов?', 'single', '[{\"id\": \"a\", \"text\": \"Образный\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Логический\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Структурный\", \"correct\": false}]', NULL, 2, 4),
(65, 7, 'Человек со структурным стилем мышления предпочитает:', 'single', '[{\"id\": \"a\", \"text\": \"Использовать готовые шаблоны и проверенные решения\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Придумывать новые алгоритмы\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Рисовать схемы\", \"correct\": false}]', NULL, 2, 5),
(66, 7, 'Напишите название стиля мышления, который связан с построением алгоритмов.', 'text', NULL, NULL, 5, 6),
(67, 7, 'К какому стилю можно отнести человека, который любит \"копаться\" в коде, пробовать разные библиотеки?', 'single', '[{\"id\": \"a\", \"text\": \"Исследовательский\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Логический\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Образный\", \"correct\": false}]', NULL, 2, 7),
(68, 7, 'Что важнее для человека с логическим стилем?', 'single', '[{\"id\": \"a\", \"text\": \"Корректность и последовательность\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Красота интерфейса\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Быстрый результат\", \"correct\": false}]', NULL, 2, 8),
(69, 7, 'Какой стиль мышления чаще всего требуется для работы с большими данными?', 'single', '[{\"id\": \"a\", \"text\": \"Логический\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Образный\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Исследовательский\", \"correct\": false}]', NULL, 2, 9),
(70, 7, 'Какие инструменты чаще использует человек с образным мышлением?', 'single', '[{\"id\": \"a\", \"text\": \"Графические редакторы\", \"correct\": true}, {\"id\": \"b\", \"text\": \"Компиляторы\", \"correct\": false}, {\"id\": \"c\", \"text\": \"Отладчики\", \"correct\": false}]', NULL, 2, 10);
INSERT INTO `test_quests` (`id`, `test_id`, `title`, `description`, `type`, `content`, `options`, `points`, `order_index`) VALUES
(1, 1, 'Знакомство с профессией', 'Узнайте больше о выбранной сфере', 'info', 'Вы выбрали направление, связанное с аналитикой. Предлагаем вам ознакомиться с кратким описанием типичного рабочего дня аналитика.', NULL, 10, 1),
(2, 1, 'Выбор специализации', 'В какой области вы хотели бы развиваться?', 'choice', 'Аналитика бывает разных видов. Выберите наиболее привлекательное направление:', '[{\"label\": \"Data Scientist (работа с большими данными и ML)\", \"value\": \"data_scientist\", \"points\": 5}, {\"label\": \"Бизнес-аналитик (анализ бизнес-процессов)\", \"value\": \"business_analyst\", \"points\": 5}, {\"label\": \"Системный аналитик (проектирование IT-систем)\", \"value\": \"system_analyst\", \"points\": 5}]', 0, 2),
(3, 1, 'Почему именно это?', 'Напишите кратко, чем вас привлекает выбранная специализация', 'text', 'Поделитесь своими мыслями: почему вас заинтересовала именно эта область? Это поможет нам лучше понять ваши предпочтения.', NULL, 10, 3),
(4, 3, 'Знакомство с миром программирования', 'Краткий обзор профессий в IT', 'info', 'Программирование охватывает множество направлений: веб-разработка, мобильная разработка, системное программирование, анализ данных и многое другое. Выбор специализации зависит от ваших интересов и склада ума.', NULL, 10, 1),
(5, 3, 'Выбор направления', 'Какое направление вам ближе?', 'choice', 'Определите, какая область программирования кажется вам наиболее привлекательной:', '[{\"label\": \"Веб-разработка (frontend/backend)\", \"value\": \"web\", \"points\": 5}, {\"label\": \"Мобильная разработка (iOS/Android)\", \"value\": \"mobile\", \"points\": 5}, {\"label\": \"Data Science и машинное обучение\", \"value\": \"data\", \"points\": 5}]', 5, 2),
(6, 3, 'Почему именно это?', 'Поделитесь своими мыслями', 'text', 'Напишите, чем вас привлекает выбранное направление. Это поможет нам лучше понять ваши предпочтения.', NULL, 10, 3),
(7, 4, 'Языки программирования', 'Краткий обзор популярных языков', 'info', 'Существует множество языков программирования, каждый со своей философией и областью применения. Python известен простотой, Java — надёжностью, JavaScript — вездесущностью в вебе, C++ — производительностью.', NULL, 10, 1),
(8, 4, 'Какой стиль вам ближе?', 'Выберите предпочтительный стиль программирования:', 'choice', 'От этого зависит, какой язык вам может подойти:', '[{\"label\": \"Простота и скорость разработки (Python, JavaScript)\", \"value\": \"simple\", \"points\": 5}, {\"label\": \"Строгость и надёжность (Java, C#)\", \"value\": \"strict\", \"points\": 5}, {\"label\": \"Производительность и контроль (C++, Rust)\", \"value\": \"performance\", \"points\": 5}]', 5, 2),
(9, 4, 'Почему именно этот стиль?', 'Поясните свой выбор', 'text', 'Напишите, почему вам близок выбранный стиль программирования.', NULL, 10, 3),
(10, 5, 'Рабочие ситуации', 'Как вести себя в коллективе', 'info', 'В любой работе возникают сложные ситуации. Важно уметь сохранять спокойствие, находить компромиссы и эффективно взаимодействовать с коллегами.', NULL, 10, 1),
(11, 5, 'Ваша роль в команде', 'Какую роль вы обычно выбираете?', 'choice', 'В командной работе люди часто берут на себя разные роли. Какая вам ближе?', '[{\"label\": \"Лидер, берущий ответственность\", \"value\": \"leader\", \"points\": 5}, {\"label\": \"Исполнитель, надёжно выполняющий задачи\", \"value\": \"executor\", \"points\": 5}, {\"label\": \"Генератор идей, креативщик\", \"value\": \"ideas\", \"points\": 5}]', 5, 2),
(12, 5, 'Почему эта роль?', 'Объясните, почему вам комфортно в этой роли', 'text', 'Напишите несколько предложений.', NULL, 10, 3),
(13, 6, 'Типы профессий по Климову', 'Что означают типы?', 'info', 'Академик Климов выделил пять типов профессий: Человек-Природа, Человек-Техника, Человек-Человек, Человек-Знак, Человек-Художественный образ. Этот тест помогает определить вашу предрасположенность.', NULL, 10, 1),
(14, 6, 'Какая сфера вам ближе?', 'Выберите наиболее привлекательную сферу деятельности:', 'choice', 'Ориентируйтесь на свои интересы.', '[{\"label\": \"Работа с техникой (ремонт, программирование)\", \"value\": \"tech\", \"points\": 5}, {\"label\": \"Общение с людьми (продажи, обучение)\", \"value\": \"people\", \"points\": 5}, {\"label\": \"Работа с информацией (аналитика, бухгалтерия)\", \"value\": \"info\", \"points\": 5}]', 5, 2),
(15, 6, 'Почему эта сфера?', 'Расскажите, что вас привлекает в выбранной сфере', 'text', 'Напишите кратко.', NULL, 10, 3),
(16, 7, 'Стили мышления в программировании', 'Что это такое?', 'info', 'У каждого программиста свой подход к решению задач: кто-то любит строить стройные логические конструкции, кто-то мыслит образами, кто-то предпочитает экспериментировать, а кто-то — использовать готовые шаблоны. Определите свой стиль.', NULL, 10, 1),
(17, 7, 'Какой подход вам ближе?', 'Выберите предпочитаемый способ решения задач:', 'choice', 'Это поможет определить ваш стиль мышления.', '[{\"label\": \"Аналитический, пошаговый (логика)\", \"value\": \"logic\", \"points\": 5}, {\"label\": \"Визуальный, через образы (дизайн)\", \"value\": \"visual\", \"points\": 5}, {\"label\": \"Экспериментальный, метод проб и ошибок (исследование)\", \"value\": \"experimental\", \"points\": 5}]', 5, 2),
(18, 7, 'Почему именно так?', 'Поясните, почему вам удобен этот подход', 'text', 'Напишите пару предложений.', NULL, 10, 3),
(19, 3, 'Знакомство с миром программирования', 'Краткий обзор профессий в IT', 'info', 'Программирование охватывает множество направлений: веб-разработка, мобильная разработка, системное программирование, анализ данных и многое другое. Выбор специализации зависит от ваших интересов и склада ума.', NULL, 10, 1),
(20, 3, 'Выбор направления', 'Какое направление вам ближе?', 'choice', 'Определите, какая область программирования кажется вам наиболее привлекательной:', '[{\"label\": \"Веб-разработка (frontend/backend)\", \"value\": \"web\", \"points\": 5}, {\"label\": \"Мобильная разработка (iOS/Android)\", \"value\": \"mobile\", \"points\": 5}, {\"label\": \"Data Science и машинное обучение\", \"value\": \"data\", \"points\": 5}]', 5, 2),
(21, 3, 'Почему именно это?', 'Поделитесь своими мыслями', 'text', 'Напишите, чем вас привлекает выбранное направление. Это поможет нам лучше понять ваши предпочтения.', NULL, 10, 3),
(22, 4, 'Языки программирования', 'Краткий обзор популярных языков', 'info', 'Существует множество языков программирования, каждый со своей философией и областью применения. Python известен простотой, Java — надёжностью, JavaScript — вездесущностью в вебе, C++ — производительностью.', NULL, 10, 1),
(23, 4, 'Какой стиль вам ближе?', 'Выберите предпочтительный стиль программирования:', 'choice', 'От этого зависит, какой язык вам может подойти:', '[{\"label\": \"Простота и скорость разработки (Python, JavaScript)\", \"value\": \"simple\", \"points\": 5}, {\"label\": \"Строгость и надёжность (Java, C#)\", \"value\": \"strict\", \"points\": 5}, {\"label\": \"Производительность и контроль (C++, Rust)\", \"value\": \"performance\", \"points\": 5}]', 5, 2),
(24, 4, 'Почему именно этот стиль?', 'Поясните свой выбор', 'text', 'Напишите, почему вам близок выбранный стиль программирования.', NULL, 10, 3),
(25, 5, 'Рабочие ситуации', 'Как вести себя в коллективе', 'info', 'В любой работе возникают сложные ситуации. Важно уметь сохранять спокойствие, находить компромиссы и эффективно взаимодействовать с коллегами.', NULL, 10, 1),
(26, 5, 'Ваша роль в команде', 'Какую роль вы обычно выбираете?', 'choice', 'В командной работе люди часто берут на себя разные роли. Какая вам ближе?', '[{\"label\": \"Лидер, берущий ответственность\", \"value\": \"leader\", \"points\": 5}, {\"label\": \"Исполнитель, надёжно выполняющий задачи\", \"value\": \"executor\", \"points\": 5}, {\"label\": \"Генератор идей, креативщик\", \"value\": \"ideas\", \"points\": 5}]', 5, 2),
(27, 5, 'Почему эта роль?', 'Объясните, почему вам комфортно в этой роли', 'text', 'Напишите несколько предложений.', NULL, 10, 3),
(28, 6, 'Типы профессий по Климову', 'Что означают типы?', 'info', 'Академик Климов выделил пять типов профессий: Человек-Природа, Человек-Техника, Человек-Человек, Человек-Знак, Человек-Художественный образ. Этот тест помогает определить вашу предрасположенность.', NULL, 10, 1),
(29, 6, 'Какая сфера вам ближе?', 'Выберите наиболее привлекательную сферу деятельности:', 'choice', 'Ориентируйтесь на свои интересы.', '[{\"label\": \"Работа с техникой (ремонт, программирование)\", \"value\": \"tech\", \"points\": 5}, {\"label\": \"Общение с людьми (продажи, обучение)\", \"value\": \"people\", \"points\": 5}, {\"label\": \"Работа с информацией (аналитика, бухгалтерия)\", \"value\": \"info\", \"points\": 5}]', 5, 2),
(30, 6, 'Почему эта сфера?', 'Расскажите, что вас привлекает в выбранной сфере', 'text', 'Напишите кратко.', NULL, 10, 3),
(31, 7, 'Стили мышления в программировании', 'Что это такое?', 'info', 'У каждого программиста свой подход к решению задач: кто-то любит строить стройные логические конструкции, кто-то мыслит образами, кто-то предпочитает экспериментировать, а кто-то — использовать готовые шаблоны. Определите свой стиль.', NULL, 10, 1),
(32, 7, 'Какой подход вам ближе?', 'Выберите предпочитаемый способ решения задач:', 'choice', 'Это поможет определить ваш стиль мышления.', '[{\"label\": \"Аналитический, пошаговый (логика)\", \"value\": \"logic\", \"points\": 5}, {\"label\": \"Визуальный, через образы (дизайн)\", \"value\": \"visual\", \"points\": 5}, {\"label\": \"Экспериментальный, метод проб и ошибок (исследование)\", \"value\": \"experimental\", \"points\": 5}]', 5, 2),
(33, 7, 'Почему именно так?', 'Поясните, почему вам удобен этот подход', 'text', 'Напишите пару предложений.', NULL, 10, 3);
